SELECT id, name, country, city, signup_date, is_active, FIRST_VALUE(age, TRUE) OVER (PARTITION BY country ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_age, MAX(age) OVER w_part AS segment_max_age, AVG(age) OVER (ORDER BY credit_limit, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS age_avg_3_prior, SUM(age) OVER w_part_2 AS running_age, MIN(credit_limit) OVER w_recent AS signup_date_period_min_credit_limit FROM customers WINDOW w_part AS (PARTITION BY segment), w_part_2 AS (PARTITION BY YEAR(signup_date), country ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_recent AS (PARTITION BY DATE_TRUNC('WEEK', signup_date), city)
